insert into public.ads (id, slug, brand_name, title, year, description, origin, source_name, source_url, seed_thread_url, created_at, is_published)
values
  ('00000000-0000-0000-0000-000000000001', 'duolingo-dua-lipa-2024', 'Duolingo', 'Learn a language, or the owl finds you', 2024, 'Duolingo extended its unhinged-mascot bit — including a staged ''death'' of Duo the owl and a cameo-style tie-in around Dua Lipa''s album cycle — leaning entirely on organic-feeling stunts rather than traditional media spend. The strategy mirrors the brand''s long-running approach of treating its app-store notifications and social account as the actual ad unit.', 'seed', 'Ad Age — industry coverage', 'https://adage.com', null, '2024-04-01T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000002', 'cerave-michael-cera-2024', 'CeraVe', 'It''s CeraVe. He''s Michael Cera. Coincidence?', 2024, 'CeraVe built a mockumentary-style campaign around the coincidence of Michael Cera''s name, running teaser content for weeks before revealing the joke in a Super Bowl spot. It''s a rare case of a clinical, dermatologist-endorsed skincare brand using absurdist celebrity comedy instead of the category''s usual efficacy-first messaging.', 'seed', 'AdWeek — industry coverage', 'https://www.adweek.com', null, '2024-02-08T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000003', 'state-farm-jake-2024', 'State Farm', 'Like a good neighbor, Jake is there', 2024, 'State Farm continued to lean on its ''Jake from State Farm'' character, pairing him with athlete cameos across digital cutdowns rather than a single hero spot. The insurer''s decade-plus consistency with the same mascot is unusual in a category that typically rotates spokespeople every few years.', 'seed', 'Marketing Dive — industry coverage', 'https://www.marketingdive.com', null, '2024-03-15T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000004', 'liquid-death-convicted-2024', 'Liquid Death', 'Convicted of loving Liquid Death too much', 2024, 'Liquid Death cast real people who had been fired, arrested, or otherwise gotten in trouble for their devotion to the brand, framing canned water with the visual language of a heavy-metal energy drink. The joke only works because the product itself is unglamorous — comedy is doing the differentiation that flavor or price would do for a normal beverage brand.', 'seed', 'Ad Age — industry coverage', 'https://adage.com', null, '2024-06-10T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000005', 'poppi-super-bowl-2025', 'Poppi', 'The soda that loves your gut back', 2025, 'Poppi paired a Super Bowl broadcast spot with a QR-code vending stunt at the stadium, betting that a functional-beverage pitch (prebiotics, low sugar) could work inside a category historically sold on nostalgia and taste. The stunt drew as much commentary for its execution and subsequent backlash as for the ad itself, a reminder that experiential add-ons carry their own reputational risk.', 'seed', 'AdWeek — industry coverage', 'https://www.adweek.com', null, '2025-02-09T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000006', 'mint-mobile-ryan-reynolds-2024', 'Mint Mobile', 'Premium wireless. Shockingly cheap.', 2024, 'Mint Mobile kept running low-budget-styled Ryan Reynolds cutdowns direct-to-camera, a format built to look inexpensive on purpose — the joke is part of the pitch that the carrier passes savings to customers. The ongoing cadence of short, meme-ready clips is built for the Ad Library format as much as for TV.', 'seed', 'Marketing Dive — industry coverage', 'https://www.marketingdive.com', null, '2024-05-20T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000007', 'openai-chatgpt-super-bowl-2025', 'OpenAI', 'The dawn of a new AI', 2025, 'OpenAI''s first paid Super Bowl spot leaned on sweeping, humanist imagery rather than a product demo, treating ChatGPT as a moment-of-history event instead of a software feature. It''s a notable pivot for a company that grew almost entirely on word-of-mouth and developer buzz, now buying attention alongside legacy consumer brands.', 'seed', 'Ad Age — industry coverage', 'https://adage.com', null, '2025-02-09T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000008', 'perplexity-ask-anything-2024', 'Perplexity', 'Skip the search. Get the answer.', 2024, 'Perplexity''s paid social creative positions the product directly against traditional search — screenshots of a cluttered results page next to a clean cited answer — rather than explaining what an ''AI answer engine'' is from scratch. The direct-comparison format is a common challenger-brand move: define yourself by what you replace, not what you are.', 'seed', 'TechCrunch — industry coverage', 'https://techcrunch.com', null, '2024-09-12T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-000000000009', 'robinhood-gold-card-2024', 'Robinhood', 'The card that pays you back', 2024, 'Robinhood''s Gold Card launch ads used a waitlist-and-scarcity framing — a physical card with a visible serial number — to borrow the cachet of exclusive credit products while undercutting them on cash-back terms. The creative deliberately looks like a luxury-card ad, a departure from Robinhood''s earlier, more utilitarian trading-app messaging.', 'seed', 'TechCrunch — industry coverage', 'https://techcrunch.com', null, '2024-05-08T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000a', 'cash-app-block-2024', 'Cash App', 'Money moves different here', 2024, 'Cash App''s creative continues to run through artist and creator partnerships rather than product-feature explainers, treating the Cash Card''s design drops as a cultural object first and a debit card second. The approach mirrors streetwear marketing more than fintech marketing, which is part of how the brand differentiates from Venmo and Zelle.', 'seed', 'Marketing Dive — industry coverage', 'https://www.marketingdive.com', null, '2024-11-01T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000b', 'whoop-4-unlock-2024', 'Whoop', 'Unlock your body''s data', 2024, 'Whoop''s ads foreground recovery and strain scores over step counts, targeting a more data-literate fitness audience than the broader wearables market. The subscription-hardware model (the band itself is nominally free with membership) is unusual enough that a chunk of the creative has to do the work of explaining the business model, not just the device.', 'seed', 'TechCrunch — industry coverage', 'https://techcrunch.com', null, '2024-05-08T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000c', 'stanley-quencher-2024', 'Stanley', 'The tumbler that survived a burning car', 2024, 'Stanley''s marketing largely amplified a customer''s own viral video of a Quencher tumbler surviving a car fire with the ice inside still intact, rather than originating the moment itself — the brand''s paid media picked up and re-cut existing organic content. It''s a case study in a 100-year-old outdoor-gear company repositioning around limited-edition colorways and collector culture instead of durability alone.', 'seed', 'Ad Age — industry coverage', 'https://adage.com', null, '2024-01-20T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000d', 'crumbl-weekly-menu-2024', 'Crumbl', 'This week''s flavors are already gone', 2024, 'Crumbl''s ads are structured entirely around scarcity and a weekly release cadence, mirroring sneaker-drop marketing more than fast-casual food marketing. The rotating menu gives the brand a reason to post new creative every single week without needing a new campaign concept — the calendar is the campaign.', 'seed', 'Marketing Dive — industry coverage', 'https://www.marketingdive.com', null, '2024-08-05T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000e', 'ag1-foundational-nutrition-2024', 'AG1', 'One scoop, foundational nutrition', 2024, 'AG1 (formerly Athletic Greens) rebranded around the vaguer, more defensible term ''foundational nutrition'' rather than specific health claims, a common move for supplement brands navigating regulatory scrutiny. Its ad creative leans heavily on subscription-and-ritual framing — the daily scoop as habit — over any single ingredient story.', 'seed', 'AdWeek — industry coverage', 'https://www.adweek.com', null, '2024-03-01T00:00:00.000Z', true),
  ('00000000-0000-0000-0000-00000000000f', 'instacart-add-to-cart-2024', 'Instacart', 'Add it to the cart', 2024, 'Instacart''s Super Bowl spot built its visual gag around edible art made from grocery items, a way to make a fundamentally logistics-driven service (delivery, routing, warehouses) feel colorful and food-forward on screen. The category''s ads increasingly compete on the emotional register of home cooking rather than convenience or speed alone.', 'seed', 'Ad Age — industry coverage', 'https://adage.com', null, '2024-02-08T00:00:00.000Z', true)
