-- studynewads seed data
-- ~15 real, notable digital ad campaigns from the last 2 years, for a fresh
-- local/dev Supabase project so the site isn't empty before Gumloop is wired
-- up. Generated from data/seed-ads.json — edit that file and regenerate
-- rather than hand-editing this one.
--
-- Do NOT run this against the already-populated production database — it
-- will add these 15 demo rows alongside whatever Gumloop/the research agent
-- has already written. Only intended for a brand-new Supabase project.
--
-- Safe to re-run on its own target: ads are upserted by slug, and each ad's
-- images are replaced (deleted + reinserted) rather than duplicated.

on conflict (slug) do update set
  brand_name = excluded.brand_name,
  title = excluded.title,
  year = excluded.year,
  description = excluded.description,
  origin = excluded.origin,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  seed_thread_url = excluded.seed_thread_url,
  is_published = excluded.is_published;

delete from public.ad_images where ad_id in ('00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', '00000000-0000-0000-0000-00000000000c', '00000000-0000-0000-0000-00000000000d', '00000000-0000-0000-0000-00000000000e', '00000000-0000-0000-0000-00000000000f');

